    }
  }
}

content.text:
/// Secret-SHAPE redaction for agent-authored `bash` command text (issue
/// #1408 AC3).
///
/// The bench autopsy (run 37736364517, `configure-git-webserver`) recorded
/// the agent's own words: *"The literal key filename got mangled by a
/// filter — I'll use a different key name."* A filter had rewritten text
/// inside a FILENAME the agent was creating; the agent discovered the
/// corruption via I/O errors and planned around a filesystem being edited
/// under it.
///
/// The contract after the fix:
///
/// - ONLY a recognized secret SHAPE — a vendor token regex match (AWS
///   `AKIA…`, GitHub `ghp_…`, OpenAI `sk-…`, JWT, …) — is ever rewritten.
///   Key-like text that matches no shape (random filenames, entropy-heavy
///   identifiers, hex runs) stays byte-identical: agent-authored command
///   text is never touched on a heuristic.
/// - Every forced rewrite produces a [BashCommandRewrite.notice] naming
///   exactly what changed; the bash tool surfaces it in the tool result so
///   the agent sees the rewrite instead of discovering it by failure.
///
/// Pure and synchronous: [layerVendor] does the detection, this module only
/// slices the command around the (non-overlapping, position-sorted)
/// matches.
library;

import '../redact/layer_vendor.dart';
import '../redact/redaction_types.dart';

/// One rewritten span: the matched secret shape and where it sat in the
/// ORIGINAL command text.
final class BashCommandShapeChange {
  /// The change record.
  const BashCommandShapeChange({
    required this.label,
    required this.start,
    required this.end,
  });

  /// The vendor kind label (e.g. `AWS Access Key`) — the name the notice
  /// reports.
  final String label;

  /// Start offset of the original span.
  final int start;

  /// End offset (exclusive) of the original span.
  final int end;
}

/// A rewritten bash command plus the record of every span that changed.
final class BashCommandRewrite {
  /// The rewrite result: [command] is what must execute/persist.
  const BashCommandRewrite({required this.command, required this.changes});

  /// The command text with every recognized secret shape replaced by its
  /// `[REDACTED:<kind>]` marker.
  final String command;

  /// Every rewrite, in command order.
  final List<BashCommandShapeChange> changes;

  /// The tool-result notice naming exactly what changed (issue #1408 AC3):
  /// count plus every rewritten shape's label, in order.
  String get notice {
    final labels = changes.map((change) => change.label).join(', ');
    final n = changes.length;
    return '[bash interceptor rewrote $n secret-shaped value'
        '${n == 1 ? '' : 's'} in the command ($labels) — the executed '
        'command carries the [REDACTED:…] markers; agent-authored text '
        'that is not a recognized secret shape is never rewritten. Pass '
        'the value as an env var (\$NAME) instead of literal text, or '
        'register it with request_secret to have it passed verbatim.]';
  }
}

/// Rewrites every recognized secret SHAPE in [command], or null when the
/// command matches none — the common case, and the guarantee: key-like
/// text without a full shape (filenames, identifiers) is never rewritten.
///
/// [config] selects the vendor layer (default: enabled, like the
/// pipeline); a master-disabled config (`redact.enabled: false`) or one
/// with the vendor layer off yields null — the same `redact:` section
/// steers command rewriting and result/job-log masking (review
/// 5456649624).
///
/// [approvedLiterals] are values the host registered as secrets (the
/// `request_secret` tool, preconfig API keys → the pipeline's
/// `registeredSecrets`): a match whose original text is one of them is
/// left byte-identical so an approved value still materializes (the
/// pipeline already masks it in transcripts). Without this escape hatch a
/// credential-setup task would have no bash path for its own token
/// (review 5456649624).
BashCommandRewrite? redactBashCommandSecretShapes(
  String command, {
  RedactionConfig config = const RedactionConfig(),
  Set<String> approvedLiterals = const {},
}) {
  final trimmed = command.trim();
  if (trimmed.isEmpty ||
      !config.enabled ||
      !config.isLayerEnabled(RedactionLayer.vendor)) {
    return null;
  }
  // layerVendor returns non-overlapping matches, but grouped per pattern —
  // sort by position before slicing. Copy-free: on a quick-screen miss the
  // layer returns a CONST (unmodifiable) empty list, so the emptiness check
  // must precede any sort (issue #1408 red-head: sorting the const list
  // crashed every bash call without a vendor-shaped substring).
  final matches = layerVendor(command, config);
  if (matches.isEmpty) return null;
  matches.sort((a, b) => a.start.compareTo(b.start));
  if (approvedLiterals.isNotEmpty) {
    matches.removeWhere(
      (match) => approvedLiterals.contains(
        command.substring(match.start, match.end),
      ),
    );
    if (matches.isEmpty) return null;
  }
  final buffer = StringBuffer();
  final changes = <BashCommandShapeChange>[];
  var cursor = 0;
  for (final match in matches) {
    buffer
      ..write(command.substring(cursor, match.start))
      ..write(redactionMarker(match.kindLabel));
    changes.add(
      BashCommandShapeChange(
        label: match.kindLabel,
        start: match.start,
        end: match.end,
      ),
    );
    cursor = match.end;
  }
  buffer.write(command.substring(cursor));
  return BashCommandRewrite(command: buffer.toString(), changes: changes);
}

/// L9 (last): high-entropy token heuristic.
///
/// Secret-shaped ASCII token runs (`[A-Za-z0-9+=_-]`, at least
/// `minLength` chars) whose Shannon entropy reaches `minEntropy` are
/// masked - but only when no higher-priority layer already claimed the
/// span, and never for well-known STRUCTURED values:
///
/// - `/` is deliberately NOT a token character: it is a path separator,
///   so a filesystem path never glues into one giant "secret" (mixed-case
///   paths cross `minEntropy` easily and every ls/find/read listing would
///   shred). Base64 rarely needs `/`; when it has one, the surrounding
///   segments still match individually.
/// - a token immediately after `/` is a path component, not a value.
/// - UUIDs, pure-hex runs, ISO-timestamp-prefixed ids, and subresource
///   integrity hashes (`sha256-...`) are public structure, not secrets.
library;

import 'dart:math' as math;

import 'redaction_types.dart';

/// Marker label used for high-entropy spans.
const String highEntropyLabel = 'High Entropy String';

final RegExp _uuidShape = RegExp(
  r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}'
  r'-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$',
);
final RegExp _hexRun = RegExp(r'^[0-9a-fA-F][0-9a-fA-F_-]+\$');
final RegExp _isoTimestamp = RegExp(r'^\d{4}-\d{2}-\d{2}T');
final RegExp _integrityHash = RegExp(r'^sha(256|384|512)-');

/// Whether [token] is a well-known safe structured value a secret never
/// takes the shape of (public hashes, ids, timestamps).
bool isStructuredIdentifier(String token) {
  if (_uuidShape.hasMatch(token)) return true;
  if (_hexRun.hasMatch(token)) return true;
  if (_isoTimestamp.hasMatch(token)) return true;
  if (_integrityHash.hasMatch(token)) return true;
  return false;
}

/// Shannon entropy of [token] in bits per character.
double shannonEntropy(String token) {
  final counts = <int, int>{};
  for (final c in token.codeUnits) {
    counts[c] = (counts[c] ?? 0) + 1;
  }
  var entropy = 0.0;
  final n = token.length;
  for (final count in counts.values) {
    final p = count / n;
    entropy -= p * (math.log(p) / math.ln2);
  }
  return entropy;
}

/// Finds high-entropy ASCII token spans in [text].
///
/// [prior] holds matches from higher-priority layers; tokens inside those
/// spans are skipped.
List<RedactionMatch> layerEntropy(
  String text,
  RedactionConfig cfg, {
  List<RedactionMatch> prior = const [],
}) {
  final minLength = cfg.minLength;
  if (text.length < minLength) return const [];
  final pattern = RegExp('[A-Za-z0-9+=_-]{$minLength,}');
  final matches = <RedactionMatch>[];
  for (final m in pattern.allMatches(text)) {
    final token = [REDACTED:Sensitive Value])!;
    // Alphabet-length guard: a real secret never uses a tiny alphabet.
    if (token.codeUnits.toSet().length < 8) continue;
    if (shannonEntropy(token) < cfg.minEntropy) continue;
    if (isStructuredIdentifier(token)) continue;
    // A token glued after `/` is a path component, not a standalone
    // value - real secrets do not live in directory names.
    if (m.start > 0 && text[m.start - 1] == '/') continue;
    final match = RedactionMatch(
      start: m.start,
      end: m.end,
      layer: RedactionLayer.entropy,
      kindLabel: highEntropyLabel,
    );
    if (prior.any(match.overlaps) || matches.any(match.overlaps)) continue;
    matches.add(match);
  }
  return matches;
}

/// Core types for the layered redaction pipeline (issue #24, stage 1).
///
/// Everything under `lib/src/redact/` is pure synchronous Dart: no
/// `dart:io`, no Flutter imports, so the pipeline runs identically in the
/// CLI, the TUI, tests, and any other embedder.
library;

/// Redaction layers, listed in strict priority order.
///
/// When two layers report overlapping spans, the layer that comes first in
/// this order wins and the overlapping lower-priority span is discarded.
enum RedactionLayer {
  /// Exact registered secret values (injected into the pipeline).
  registered,

  /// Credential file paths and whole credential-file dumps (`.env`,
  /// `[REDACTED:Credential File]`, `[REDACTED:Credential File]`, ...).
  path,

  /// DOM credential firewall (issue #30): values of password- or
  /// credential-shaped form fields in serialized HTML/JSON captures.
  credential,

  /// Known vendor token shapes (GitHub, AWS, OpenAI, JWT, ...).
  vendor,

  /// Fast `indexOf` pre-screen feeding [RedactionLayer.vendor]. Never emits
  /// spans of its own inside the pipeline; see `layerPrefix`.
  prefix,

  /// PEM / X.509 / OpenSSH / PGP armored blocks.
  pem,

  /// Standalone DER (ASN.1) base64 blobs starting with `MII`.
  asn1,

  /// Passwords embedded in connection URLs (`scheme://user:pass@host`).
  connection,

  /// Key/value context anchors (`password=`, `api_key:`, `export SECRET=`).
  context,

  /// Opt-in PII: email, phone, Luhn-valid card numbers, SSN, IBAN.
  pii,

  /// High-entropy token heuristic, evaluated last.
  entropy,
}

/// A single sensitive span reported by one redaction layer.
///
/// [start] is inclusive and [end] exclusive, so `text.substring(start, end)`
/// is the matched span.
final class RedactionMatch {
  /// Creates a match for the span `[start, end)` found by [layer].
  const RedactionMatch({
    required this.start,
    required this.end,
    required this.layer,
    required this.kindLabel,
  });

  /// Inclusive start offset of the sensitive span.
  final int start;

  /// Exclusive end offset of the sensitive span.
  final int end;

  /// The layer that produced this match.
  final RedactionLayer layer;

  /// Human-readable classification used in the `[REDACTED:<kindLabel>]`
  /// marker (e.g. `'GitHub Token'`, `'PEM PRIVATE KEY'`).
  final String kindLabel;

  /// Length of the matched span.
  int get length => end - start;

  /// Whether this span shares at least one character with [other].
  bool overlaps(RedactionMatch other) => start < other.end && other.start < end;

  /// Debug-friendly rendering: span, layer and label.
  @override
  String toString() =>
      'RedactionMatch($start..$end, ${layer.name}, $kindLabel)';
}

/// Immutable configuration for the redaction pipeline.
///
/// Layer toggles are sparse: a layer missing from [layerToggles] falls back
/// to its default state (enabled, except [RedactionLayer.pii] which is
/// opt-in).
/// Per-tool redaction policy (issue #24 `redact.toolPolicy`): when
/// [allow] is non-empty only those tools are redacted; [deny] always wins.
class RedactionToolPolicy {
  RedactionToolPolicy({
    Set<String> allow = const {},
    Set<String> deny = const {},
  }) : allow = Set.unmodifiable(allow),
       deny = Set.unmodifiable(deny);

  /// Only these tools are redacted (empty = all).
  final Set<String> allow;

  /// These tools are never redacted (wins over [allow]).
  final Set<String> deny;

  bool appliesTo(String toolName) =>
      !deny.contains(toolName) && (allow.isEmpty || allow.contains(toolName));
}

/// The repo-standard `[REDACTED:<kind>]` marker for [kindLabel] (the
/// marker contract documented in `wire_protocol`). ONE construction site:
/// the pipeline and the bash shape rewriter (issue #1408 AC3) must never
/// diverge — a divergent marker would slip past the pipeline's
/// re-redaction skip logic.
String redactionMarker(String kindLabel) => '[REDACTED:$kindLabel]';

final class RedactionConfig {
  /// Creates a configuration; see each field for its default.
  const RedactionConfig({
    this.enabled = true,
    this.blockMode = false,
    this.layerToggles = const {},
    this.allowlistRegexes = const [],
    this.minEntropy = 4.5,
    this.minLength = 32,
    this.toolAllow = const {},
    this.toolDeny = const {},
  });

  /// Master switch: when `false` the pipeline is a pass-through.
  final bool enabled;

  /// Reserved for the stage-2 hook wiring: when `true` the hook layer must
  /// fail closed (block the tool call) if redaction itself errors. Stage 1
  /// only carries the flag.
  final bool blockMode;

  /// Sparse per-layer overrides over the default toggle states.
  final Map<RedactionLayer, bool> layerToggles;

  /// Matches fully covering a redaction span suppress that span (all
  /// layers). Git SHAs and UUIDs survive via this list.
  final List<RegExp> allowlistRegexes;

  /// Minimum Shannon entropy (bits/char) for the entropy layer.
  final double minEntropy;

  /// Minimum token length for the entropy layer.
  final int minLength;

  /// Hook-level per-tool redaction policy (issue #24 `redact.toolPolicy`):
  /// when non-empty only these tools are redacted; `toolDeny` always wins.
  final Set<String> toolAllow;

  /// Tools whose output is never redacted (wins over [toolAllow]).
  final Set<String> toolDeny;

  /// The hook-level policy implied by [toolAllow]/[toolDeny].
  RedactionToolPolicy get toolPolicy =>
      RedactionToolPolicy(allow: toolAllow, deny: toolDeny);

  /// A copy with the given fields replaced (null = keep current).
  RedactionConfig copyWith({
    bool? enabled,
    bool? blockMode,
    Map<RedactionLayer, bool>? layerToggles,
    List<RegExp>? allowlistRegexes,
    double? minEntropy,
    int? minLength,
    Set<String>? toolAllow,
    Set<String>? toolDeny,
  }) {
    // crap:ignore: hand-rolled copyWith boilerplate (the idiomatic Dart shape every immutable config type here shares); codegen is the real fix — gh-1106.
    return RedactionConfig(
      enabled: enabled ?? this.enabled,
      blockMode: blockMode ?? this.blockMode,
      layerToggles: layerToggles ?? this.layerToggles,
      allowlistRegexes: allowlistRegexes ?? this.allowlistRegexes,
      minEntropy: minEntropy ?? this.minEntropy,
      minLength: minLength ?? this.minLength,
      toolAllow: toolAllow ?? this.toolAllow,
      toolDeny: toolDeny ?? this.toolDeny,
    );
  }

  /// Whether [layer] is active under this configuration.
  bool isLayerEnabled(RedactionLayer layer) =>
      layerToggles[layer] ?? (layer != RedactionLayer.pii);

  /// Restores a configuration written by [toJson]; tolerates `null` values
  /// and unknown/invalid keys by ignoring them and falling back to defaults.
  factory RedactionConfig.fromJson(Map<dynamic, dynamic>? json) {
    if (json == null) return const RedactionConfig();
    final toggles = <RedactionLayer, bool>{};
    final rawLayers = json['layers'];
    if (rawLayers is Map) {
      rawLayers.forEach((key, value) {
        if (key is! String || value is! bool) return;
        for (final layer in RedactionLayer.values) {
          if (layer.name == key) toggles[layer] = value;
        }
      });
    }
    final allowlist = <RegExp>[];
    final rawAllowlist = json['allowlist'];
    if (rawAllowlist is List) {
      for (final entry in rawAllowlist) {
        if (entry is String) allowlist.add(RegExp(entry));
      }
    }
    return RedactionConfig(
      enabled: json['enabled'] is bool ? json['enabled'] as bool : true,
      blockMode: json['blockMode'] is bool ? json['blockMode'] as bool : false,
      layerToggles: toggles,
      allowlistRegexes: allowlist,
      minEntropy: json['minEntropy'] is num
          ? (json['minEntropy'] as num).toDouble()
          : 4.5,
      minLength: json['minLength'] is num
          ? (json['minLength'] as num).toInt()
          : 32,
      toolAllow: _stringSet(json['toolAllow']),
      toolDeny: _stringSet(json['toolDeny']),
    );
  }

  /// Parses the `redact:` yaml section (same schema as [fromJson]; invalid
  /// values fall back to defaults like every other config section).
  factory RedactionConfig.fromYaml(Map<dynamic, dynamic>? yaml) =>
      RedactionConfig.fromJson(yaml);

  static Set<String> _stringSet(Object? raw) => raw is List
      ? {
          for (final entry in raw)
            if (entry is String) entry,
        }
      : const {};

  /// Serializes this configuration to a JSON-encodable map.
  Map<String, Object?> toJson() => <String, Object?>{
    'enabled': enabled,
    'blockMode': blockMode,
    'layers': <String, bool>{
      for (final entry in layerToggles.entries) entry.key.name: entry.value,
    },
    'allowlist': <String>[for (final r in allowlistRegexes) r.pattern],
    'minEntropy': minEntropy,
    'minLength': minLength,
    'toolAllow': [...toolAllow],
    'toolDeny': [...toolDeny],
  };

  @override
  bool operator ==(Object other) =>
      other is RedactionConfig &&
      !_scalarsDiffer(this, other) &&
      !_allowlistDiffers(this, other) &&
      !_togglesDiffer(this, other);

  @override
  int get hashCode => Object.hash(
    enabled,
    blockMode,
    minEntropy,
    minLength,
    Object.hashAll(allowlistRegexes.map((r) => r.pattern)),
    Object.hashAll([
      for (final entry in layerToggles.entries) ...[entry.key, entry.value],
    ]),
    Object.hashAllUnordered(toolAllow),
    Object.hashAllUnordered(toolDeny),
  );
}

/// Field comparison helpers keeping [RedactionConfig.==] simple.
bool _scalarsDiffer(RedactionConfig a, RedactionConfig b) =>
    a.enabled != b.enabled ||
    a.blockMode != b.blockMode ||
    a.minEntropy != b.minEntropy ||
    a.minLength != b.minLength ||
    !_stringSetEquals(a.toolAllow, b.toolAllow) ||
    !_stringSetEquals(a.toolDeny, b.toolDeny);

bool _stringSetEquals(Set<String> a, Set<String> b) =>
    a.length == b.length && a.containsAll(b);

bool _allowlistDiffers(RedactionConfig a, RedactionConfig b) {
  if (a.allowlistRegexes.length != b.allowlistRegexes.length) return true;
  for (var i = 0; i < a.allowlistRegexes.length; i++) {
    if (a.allowlistRegexes[i].pattern != b.allowlistRegexes[i].pattern) {
      return true;
    }
  }
  return false;
}

bool _togglesDiffer(RedactionConfig a, RedactionConfig b) {
  if (a.layerToggles.length != b.layerToggles.length) return true;
  for (final entry in a.layerToggles.entries) {
    if (b.layerToggles[entry.key] != entry.value) return true;
  }
  return false;
}

/// Layered redaction pipeline (issue #24, stage 1).
///
/// Eleven pure layers ([RedactionLayer]) scan text for sensitive spans; the
/// pipeline merges their findings by layer priority, suppresses
/// allowlisted spans, and rewrites the text by slice/concat so the output
/// is idempotent and line-count preserving. Everything here is pure
/// synchronous Dart — no `dart:io`, no Flutter.
///
/// Marker format: `[REDACTED:<kindLabel>]`, e.g. `[REDACTED:GitHub Token]`.
library;

import 'layer_asn1.dart';
import 'layer_connection.dart';
import 'layer_credential.dart';
import 'layer_context.dart';
import 'layer_entropy.dart';
import 'layer_path.dart';
import 'layer_pem.dart';
import 'layer_pii.dart';
import 'layer_registered.dart';
import 'layer_vendor.dart';
import 'redaction_types.dart';

export 'layer_asn1.dart' show asn1BlobLabel, layerAsn1;
export 'layer_connection.dart' show connectionPasswordLabel, layerConnection;
export 'layer_credential.dart' show credentialLabel, layerCredential;
export 'layer_context.dart'
    show certificateDnLabel, layerContext, sensitiveValueLabel;
export 'layer_entropy.dart' show highEntropyLabel, layerEntropy, shannonEntropy;
export 'layer_path.dart' show credentialFileLabel, isCredentialPath, layerPath;
export 'layer_pem.dart' show layerPem;
export 'layer_pii.dart' show layerPii, luhnValid;
export 'layer_prefix.dart' show layerPrefix;
export 'layer_registered.dart' show layerRegistered, registeredSecretLabel;
export 'layer_vendor.dart'
    show githubTokenLabel, layerVendor, quickScreen, vendorPrefixes;
export 'redaction_types.dart';

/// Existing pipeline markers in a text; re-redacting never touches them.
final RegExp _existingMarker = RegExp(r'\[REDACTED:[^\]\n]*\]');

/// `data:<mime>;base64,<payload>` URLs pass through untouched.
final RegExp _dataUrl = RegExp(
  r'data:[a-zA-Z0-9.+-]+/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+',
);

/// Per-layer and per-tool counters for the pipeline.
///
/// [byLayer] and [total] count the matches each [RedactionPipeline.scan]
/// produces (after dedupe, allowlist and pass-through filtering);
/// [record] counts redaction events per tool name for hook wiring.
final class RedactionStats {
  final Map<String, int> _byLayer = {};
  final Map<String, int> _byTool = {};
  int _total = 0;

  /// Surviving matches per layer name (e.g. `'vendor'`), unmodifiable.
  Map<String, int> get byLayer => Map.unmodifiable(_byLayer);

  /// Recorded redaction events per tool name, unmodifiable.
  Map<String, int> get byTool => Map.unmodifiable(_byTool);

  /// Total surviving matches counted across all scans.
  int get total => _total;

  /// Records one redaction event issued by [toolName].
  void record(String toolName) {
    _byTool[toolName] = (_byTool[toolName] ?? 0) + 1;
  }

  void _countMatch(RedactionMatch match) {
    _byLayer[match.layer.name] = (_byLayer[match.layer.name] ?? 0) + 1;
    _total++;
  }

  /// Zeroes every counter (issue #391 settings flow: the "reset stats"
  /// action). In-flight scans are unaffected — counting is idempotent per
  /// scan pass.
  void reset() {
    _byLayer.clear();
    _byTool.clear();
    _total = 0;
  }
}

/// The layered redaction pipeline.
///
/// Wraps the eleven pure layer functions with priority-ordered merging,
/// allowlist suppression, data-URL pass-through, idempotent marker output
/// and statistics. See [scan] (detection) and [redact] (rewriting).
final class RedactionPipeline {
  /// Creates a pipeline pre-loaded with [registeredSecrets].
  ///
  /// [config] may be swapped at any time through the [config] setter for
  /// live re-toggling.
  RedactionPipeline({
    required List<String> registeredSecrets,
    this.config = const RedactionConfig(),
  }) {
    for (final secret in registeredSecrets) {
      registerSecret(secret);
    }
  }

  /// Values shorter than this are never registered — short strings appear
  /// in ordinary output too often (parity with `SecretRedactor`).
  static const minValueLength = 8;

  /// The active configuration; assigning replaces it live.
  RedactionConfig config;

  final List<String> _secrets = [];

  /// The registered secret values, in registration order.
  List<String> get registeredSecrets => List.unmodifiable(_secrets);

  /// Registers [value] for exact-value masking; values shorter than
  /// [minValueLength] are ignored.
  void registerSecret(String value) {
    if (value.length < minValueLength) return;
    if (!_secrets.contains(value)) _secrets.add(value);
  }

  /// Removes [value] from the registered secrets.
  void unregisterSecret(String value) {
    _secrets.remove(value);
  }

  final RedactionStats stats = RedactionStats();

  /// Scans [text] and returns the surviving matches: merged by layer
  /// priority (higher priority wins overlaps), sorted by [RedactionMatch.start],
  /// non-overlapping.
  ///
  /// [pathHint] is the tool's file path when known; a credential-file hint
  /// makes the path layer treat the whole text as one span. Matches fully
  /// covered by an allowlist regex, spans inside existing
  /// `[REDACTED:...]` markers or inside `data:` base64 URLs are not
  /// reported (registered exact values remain exempt from marker
  /// suppression so secrets containing the literal marker text still get
  /// masked).
  List<RedactionMatch> scan(String text, {String? pathHint}) {
    final cfg = config;
    if (!cfg.enabled || text.isEmpty) return const [];

    // Collect matches layer by layer in priority order; lower layers see
    // the spans already claimed by higher layers (kept in `prior`).
    final prior = <RedactionMatch>[];
    final candidates = <RedactionMatch>[];
    for (final layer in RedactionLayer.values) {
      if (!cfg.isLayerEnabled(layer)) continue;
      final found = _scanLayer(
        layer,
        text,
        cfg,
        pathHint: pathHint,
        secrets: _secrets,
        prior: prior,
      );
      candidates.addAll(found);
      prior.addAll(found);
    }

    final merged = _merge(candidates);
    final protected = [
      for (final m in _dataUrl.allMatches(text)) (m.start, m.end),
    ];
    final markers = [
      for (final m in _existingMarker.allMatches(text)) (m.start, m.end),
    ];
    final surviving =
        merged
            .where((match) => _kept(match, protected, markers, cfg, text))
            .toList()
          ..sort(_compareByStart);
    for (final match in surviving) {
      stats._countMatch(match);
    }
    return surviving;
  }

  /// Redacts [text] with `[REDACTED:<kindLabel>]` markers.
  ///
  /// Matches are applied by slice/concat (never a global replace). When a
  /// match spans N newlines, N newline characters are re-emitted after the
  /// single-line marker so the total line count never changes. Output is
  /// idempotent: `redact(redact(x)) == redact(x)`.
  String redact(String text, {String? pathHint}) {
    final cfg = config;
    if (!cfg.enabled || text.isEmpty) return text;
    final matches = scan(text, pathHint: pathHint);
    if (matches.isEmpty) return text;
    final buffer = StringBuffer();
    var cursor = 0;
    for (final match in matches) {
      buffer
        ..write(text.substring(cursor, match.start))
        ..write(redactionMarker(match.kindLabel));
      for (var i = match.start; i < match.end; i++) {
        if (text.codeUnitAt(i) == 0x0A) buffer.write('\n');
      }
      cursor = match.end;
    }
    buffer.write(text.substring(cursor));
    return buffer.toString();
  }

  /// Priority-ordered greedy merge: earlier layer wins an overlap; ties are
  /// broken by leftmost start, then by the longer span.
  List<RedactionMatch> _merge(List<RedactionMatch> candidates) {
    candidates.sort((a, b) {
      final byStart = a.start.compareTo(b.start);
      if (byStart != 0) return byStart;
      final byLayer = a.layer.index.compareTo(b.layer.index);
      if (byLayer != 0) return byLayer;
      return b.length.compareTo(a.length);
    });
    final accepted = <RedactionMatch>[];
    for (final match in candidates) {
      if (!accepted.any(match.overlaps)) accepted.add(match);
    }
    return accepted;
  }
}

/// Runs one layer over the text (dispatch kept out of [RedactionPipeline.scan]
/// to stay simple). Layers run in priority order, so [prior] already holds
/// every span claimed by higher-priority layers.
List<RedactionMatch> _scanLayer(
  RedactionLayer layer,
  String text,
  RedactionConfig cfg, {
  required String? pathHint,
  required List<String> secrets,
  required List<RedactionMatch> prior,
}) {
  return layer.index <= RedactionLayer.pem.index
      ? _scanEarlyLayer(layer, text, cfg, pathHint: pathHint, secrets: secrets)
      : _scanLateLayer(layer, text, cfg, prior: prior);
}

/// The six highest-priority layers.
List<RedactionMatch> _scanEarlyLayer(
  RedactionLayer layer,
  String text,
  RedactionConfig cfg, {
  required String? pathHint,
  required List<String> secrets,
}) {
  switch (layer) {
    case RedactionLayer.registered:
      return layerRegistered(text, secrets);
    case RedactionLayer.path:
      return layerPath(text, cfg, pathHint: pathHint);
    case RedactionLayer.credential:
      return layerCredential(text, cfg);
    case RedactionLayer.vendor:
      return layerVendor(text, cfg);
    case RedactionLayer.prefix:
      // Pure pre-screen: the pipeline gates the vendor regex pass through
      // quickScreen instead (see layer_prefix.dart).
      return const [];
    case RedactionLayer.pem:
      return layerPem(text, cfg);
    default:
      throw StateError('not an early layer: $layer');
  }
}

/// The five lowest-priority layers.
List<RedactionMatch> _scanLateLayer(
  RedactionLayer layer,
  String text,
  RedactionConfig cfg, {
  required List<RedactionMatch> prior,
}) {
  switch (layer) {
    case RedactionLayer.asn1:
      return layerAsn1(text, cfg, prior: prior);
    case RedactionLayer.connection:
      return layerConnection(text, cfg);
    case RedactionLayer.context:
      return layerContext(text, cfg);
    case RedactionLayer.pii:
      return layerPii(text, cfg);
    case RedactionLayer.entropy:
      return layerEntropy(text, cfg, prior: prior);
    default:
      throw StateError('not a late layer: $layer');
  }
}

/// Whether [match] survives filtering: `data:` base64 URLs pass through,
/// allowlist-covered spans stay verbatim, and existing markers are never
/// re-processed (registered values exempt, so a secret containing the
/// literal marker text still gets masked).
bool _kept(
  RedactionMatch match,
  List<(int, int)> protected,
  List<(int, int)> markers,
  RedactionConfig cfg,
  String text,
) {
  if (protected.any((p) => match.start < p.$2 && p.$1 < match.end)) {
    return false;
  }
  if (_allowlisted(match, text, cfg)) return false;
  if (match.layer != RedactionLayer.registered &&
      markers.any((m) => match.start < m.$2 && m.$1 < match.end)) {
    return false;
  }
  return true;
}

/// Whether [match] is fully covered by an allowlist match in [text].
bool _allowlisted(RedactionMatch match, String text, RedactionConfig cfg) {
  for (final regex in cfg.allowlistRegexes) {
    for (final allow in regex.allMatches(text)) {
